    static class InputReader {
        private final InputStream input;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, length = 0;

        public InputReader(InputStream input) { this.input = input; }

        private int readByte() {
            if (length == -1) throw new RuntimeException();
            if (ptr >= length) {
                ptr = 0;
                try { length = input.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (length <= 0) return -1;
            }
            return buffer[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= 32) c = readByte();
            int sign = 1;
